window.MONSTER_CHUNK_151 = [{"name":"Afanc","cr":17,"xp":102400,"alignment":"N","size":"Colossal","type":"magical beast","subtypes":["aquatic"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"telepathy","modifier":"100 ft."}],"ac":23,"ac_touch":3,"ac_flat_footed":22,"ac_mods":"+1 Dex, +20 natural, -8 size","hp":333,"hd":"23d10+207","hdvalue":23,"fort":22,"ref":14,"will":11,"dr":"15/adamantine","immunities":["poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":28,"weaknesses":["water-dependant"],"speed":[{"type":"land","speed":5},{"type":"swim","speed":60}],"melee":"bite +32 (5d6+16), 2 claws +31 (2d8+16)","space":"100 ft.","reach":"20 ft.","special_attacks":[{"type":"sea swell"},{"type":"swallow whole","details":"4d6+16 plus 8 points acid damage, AC 20, 33 hp"}],"strength":42,"dexterity":13,"constitution":28,"intelligence":3,"wisdom":15,"charisma":10,"baseatk":23,"cmb":47,"cmb_special":"+4 vs. grapple, sunder","cmd":58,"cmd_special":"can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Greater Sunder"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Swim-By Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":28},{"skill":"Swim","value":24}],"languages":["telepathy 100 ft."],"environments":["any aquatic"],"organizations":["solitary"],"treasure":"incidental","description_visual":"This massive creature appears to be a gray-skinned whale with a bulbous head similar to a catfish's. Its eyes are sullen and blue and its huge pectoral fins are serrated.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Sea Swell","kind":"Ex","details":": As a full-round action, an afanc can raise the front part of its body out of the water and bring it crashing back down against the surface. This generates massive waves up to 30 ft. tall that may capsize boats and ships within 100 ft. of the afanc. Boats and ships less than 20 ft. long automatically capsize. Boats over 20 ft. long may or may not capsize depending on the skill of the one piloting the vessel. A character steering or guiding a boat or ship over 20 ft. long that succeeds on a DC 37 Profession (sailor) check manages to keep the boat afloat; otherwise it capsizes, spilling its contents into the water. The check DC is Strength-based."}],"description":"Afancs are the sea monsters that sailors talk about when spinning tales of the sea. They are the creatures responsible for entire fleets and crews being lost or destroyed. They are thought by many to be the \"kings\" of the sea as most other water-dwellers pale in comparison both in strength and size to the mighty afanc.\n\nAfancs are omnivorous hunters of the deep sea, feeding on a mixed diet of kelp, coral, sea plants, sharks, whales, various other large fishes, and swimmers and sailors unfortunate enough to cross the path of an afanc.\n\nAfancs are sometimes worshipped as sea gods by small towns, villages, and seaside communities. Sacrifices to the \"Great Whale Gods\" include in various forms enormous amounts of cultivated sea plants, massive amounts of fish that have been netted, young girls or women, and occasionally an entire ship laden with criminals who are to be executed for their crimes.\n\nAn afanc is generally about 100 ft. long though specimens as large as 200 ft. long are thought to exist. Its whale-like body is colored gray or sometimes bluish-green and its eyes are always blue. Its tail is extremely long and ends in a truncated or flat, square edge. An afanc has a bulbous, somewhat flattened head, not unlike that of a great catfish."},{"name":"Ferrous Giant","cr":17,"xp":102400,"alignment":"N","size":"Huge","type":"humanoid","subtypes":["giant"],"init":0,"senses":[{"type":"low-light vision"}],"auras":["info"],"ac":32,"ac_touch":8,"ac_flat_footed":32,"ac_mods":"+6 armor, +18 natural, -2 size","hp":287,"hd":"25d8+175","hdvalue":25,"fort":21,"ref":8,"will":12,"dr":"15/cold iron","immunities":["fire","mind-affecting effects"],"speed":[{"type":"land","speed":50}],"melee":"greataxe +31 (4d6+22, 19-20/x3) or greatsword +31 (4d6+22, 17-20/x2); or 2 slams +31 (2d6+15 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"trample","details":"2d6+22; DC 37"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"heat metal"},{"spell":"levitate","details":"iron or steel objects or creatures only, including itself"}]},{"frequency":"1/day","spells":[{"spell":"wall of iron"}]}],"strength":40,"dexterity":11,"constitution":25,"intelligence":14,"wisdom":15,"charisma":14,"baseatk":18,"cmb":35,"cmb_special":"+4 vs. bull rush, grapple, sunder","cmd":45,"cmd_special":"+4 vs. bull rush, sunder","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Greater Bull Rush"},{"feat":"Greater Sunder"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (greatsword or greataxe)"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Craft [weaponsmithing])"},{"feat":"Staggering Critical"}],"skills":[{"skill":"Craft (any one)","value":30},{"skill":"Craft (weaponsmithing)","value":36},{"skill":"Perception","value":30},{"skill":"Spellcraft","value":27}],"languages":["Common","Giant"],"sq":[{"type":"oversized weapon use"},{"type":"weapon and armor proficiency"}],"environments":["any mountains","temperate hills","warm hills"],"organizations":["solitary","family (2-4 plus 35% noncombatants plus 1 cleric or druid of 9th-12th level)"],"treasure":"standard","description_visual":"A towering giant stands 20 ft. tall with dark, ruddy skin. His course brown hair and beard are long and wild, and he wears a thick breastplate and dozens of furs.","group":"Ferrous","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Ferrous Mind","kind":"Ex","details":"Ferrous giants are immune to mindinfluencing effects (charms, compulsions, phantasms, patterns, and morale effects)."},{"type":"Pound","kind":"Ex","details":"A ferrous giant that successfully grabs a foe two or more sizes smaller than itself can smash the opponent into the ground, walls, nearby trees, or other solid objects as a standard action. This deals 2d6+22 points of bludgeoning damage to the victim. In addition, the opponent must make a successful DC 37 Fortitude save or be stunned for one round. A ferrous giant can perform this action once per round as long as it maintains the grapple. The save DC is Strength-based."},{"type":"Oversized Weapon Use","kind":"Ex","details":"A ferrous giant wields a Gargantuan greatsword or greataxe without penalty."},{"type":"Weapon and Armor Proficiency","kind":"Ex","details":"Ferrous giants are automatically proficient with simple weapons, martial weapons, light and medium armor, and shields."}],"description":"The great ferrous giant stands over 20 ft. tall and appears as a humanoid composed of flexible and bendable iron. Though it is often mistaken for a construct, it is in fact a very intelligent giant. A ferrous giant makes its home deep within a secluded mountain range. Its lair is often a deep cave or cavern or a gigantic castle constructed of iron and built into the face of a mountain. Ferrous giants are generally solitary creatures rarely interacting or dealing with other races, including other giants. Though not on bad terms with other giants, they simply have no interest in dealing with them. Ferrous giants spend most of their days hunting (deer, moose, boar, elk) and foraging or crafting exquisite weapons of iron.\n\nSome particularly sociable ferrous giants (a rare occurrence to be assured) set up a trading operation with a nearby town or city, exchanging weapons for whatever might interest the giant (food, iron, money, etc.). In melee, the ferrous giant uses its Huge iron battleaxe or longsword to bash or cleave its opponents. If disarmed, or if it is feeling particularly vile, a ferrous giant can pummel a foe with its massive fists. When fighting smaller foes, the ferrous giant often opens combat by trampling its foes or grabbing them and flinging them aside. Particularly noisome opponents are scooped up and pounded into the ground. The ferrous giant uses its heat metal ability in combat to heat the armor of its opponents and burn its foes.","as_character":[{"description":"Ferrous giants are extremely strong, have hardy constitutions and remain versatile all other facets. Ferrous giant shamans are usually adepts or druids. Clerics can choose two of the following domains: Earth, Fire, Knowledge, and Sun.","racial_traits":[{"type":"Ability Score Bonuses","value":"+30 Strength, +15 Constitution, +2 Intelligence, +2 Wisdom, +2 Charisma"},{"type":"Huge","value":"Ferrous giants are Huge and take a -2 penalty to AC, -2 penalty to attack rolls, +2 bonus to Combat Maneuver Bonus and Combat Maneuver Defense, and a -8 penalty to Stealth checks. A ferrous giant's lifting and carrying limits quadruple those of Medium characters. Space 15ft., Reach 15ft."},{"type":"Speed","value":"A ferrous giant's base speed is 50 ft."},{"type":"Low-light vision","value":"Ferrous giants can see twice as far as humans in conditions of dim light."},{"type":"Racial Hit Dice","value":"A ferrous giant starts with twenty-five levels of humanoid, which provide it with 25d8 HD, a base attack bonus of +18, and base save bonuses of Fort +14, Ref +8, Will +8."},{"type":"Racial Skills","value":"A ferrous giant's humanoid levels give it skill ranks equal to 25 x (2 + Int modifier). Its class skill are Craft (weapons), Intimidate, and Perception."},{"type":"Racial Feats","value":"A ferrous giant's giant levels give it 12 feats."},{"type":"AC","value":"+18 natural AC bonus."},{"type":"Natural Weapons","value":"Ferrous giants can fight with 2 unarmed strikes that deal lethal damage (2d6+15)."},{"type":"Special Attacks","value":"Grab, pound, spell-like abilities, trample."},{"type":"Special Qualities","value":"Damage reduction 15/cold iron, fire immunity, ferrous mind."},{"type":"Weapon and Armor Proficiency","value":"Ferrous giants are automatically proficient with simple weapons, martial weapons, light and medium armor, and shields."},{"type":"Languages","value":"Ferrous giants begin play speaking Giant and Common. Ferrous giants with high intelligence scores can choose from the following languages: Draconic, Elven, Goblin, and Orc."}]}],"gear":"breastplate, Gargantuan greatsword or greataxe"},{"name":"Gelatinous Emperor","cr":17,"xp":102400,"alignment":"CE","size":"Huge","type":"ooze","subtypes":["chaotic","evil","extraplanar"],"init":4,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":29,"ac_touch":8,"ac_flat_footed":29,"ac_mods":"+21 natural, -2 size","hp":256,"hd":"19d8+171","hdvalue":19,"fort":17,"ref":8,"will":10,"dr":"10/magic and good","immunities":["acid","electricity","ooze traits"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"sr":28,"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"2 tentacles +23 (2d8+10 plus 2d8 acid)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"spew acid"},{"type":"trample","details":"2d8+15 plus 2d8 acid, DC 29"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"summon","details":"level 7, 1d4 black puddings 100%, 1d4 gelatinous cubes 100%, or 1d2 15 HD black puddings 50%"}]}],"strength":31,"dexterity":10,"constitution":28,"intelligence":10,"wisdom":15,"charisma":13,"baseatk":14,"cmb":26,"cmd":36,"cmd_special":"can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Critical Focus"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Staggering Critical"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Climb","value":27},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":1},{"skill":"Swim","value":19}],"languages":["Abyssal (cannot speak)"],"environments":["any (Abyss)"],"organizations":["solitary","gang (1 emperor plus 2-5 advanced black puddings)"],"treasure":"none","description_visual":"This large, reddish-brown amorphous blob moves slowly forward.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Acid","kind":"Ex","details":"A gelatinous emperor's acid doesn't harm metal or stone."},{"type":"Spew Acid","kind":"Ex","details":"A gelatinous emperor can, as a standard action, spew forth acid in a 30-foot line at a single target. A creature struck takes 12d6 points of acid damage. A DC 28 Reflex save reduces the damage by half. Once a gelatinous emperor has spewed acid, it cannot do so again for 1d4 rounds. The save DC is Constitution-based."}],"description":"Gelatinous emperors are intelligent, foul oozes found in the court of Jubilex. What purpose and in what capacity they serve the Faceless Lord is anyone's guess. From his Abyssal plane they strike out, devouring anything and everything they run across. They are eternal hunters, always moving and always hungry. When a gelatinous emperor slips into the Material Plane it quickly ravages the area leaving it devoid of all life. Thankfully these creatures are not often found on the Material Plane.\n\nA gelatinous emperor is believed to be a foul mix of gelatinous cube, gray ooze, black pudding, and all other manner of puddings and oozes meshed together by Jubilex, either for some nefarious purpose or for nothing more than his sheer amusement. Sages believe the latter to be the truer of the two theories.\n\nA gelatinous emperor attacks by forming multiple pseudopods from its amorphous body and lashing out at its opponents. If the emperor can maneuver its opponents into a tight group it employs its trample attack, crushing as many of its foes in one move as possible."},{"name":"Jack-in-irons Giant","cr":17,"xp":102400,"alignment":"CE","size":"Huge","type":"humanoid","subtypes":["giant"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":28,"ac_touch":9,"ac_flat_footed":27,"ac_mods":"+1 Dex, +19 natural, -2 size","hp":321,"hd":"26d8+204","hdvalue":26,"fort":23,"ref":11,"will":1,"defensive_abilities":["rock catching"],"speed":[{"type":"land","speed":40}],"melee":"spiked greatclub +31 (3d8+19 plus daze) or great chain +31 (2d8+13 plus daze) or 2 slams +30 (2d6+13 plus daze)","ranged":"rock +19 (2d6+19)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"daze"},{"type":"pound"},{"type":"rock throwing","details":"140 ft."},{"type":"shake the earth"},{"type":"trample","details":"2d6+19, DC 36"}],"strength":36,"dexterity":12,"constitution":26,"intelligence":10,"wisdom":14,"charisma":11,"baseatk":19,"cmb":0,"cmd":12,"cmd_special":"+4 vs. trip","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Endurance"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Martial Weapon Proficiency (great chain)"},{"feat":"Martial Weapon Proficiency (greatclub)"},{"feat":"Power Attack"},{"feat":"Weapon Focus (greatclub)"},{"feat":"Weapon Focus (chain)"}],"skills":[{"skill":"Climb","value":18},{"skill":"Intimidate","value":25},{"skill":"Perception","value":27},{"skill":"Survival","value":11}],"languages":["Giant"],"environments":["temperate forests","temperate plains"],"organizations":["solitary"],"treasure":"standard","description_visual":"Brutish, warty, hairy, and stinking of oil and iron, this creature has a jutting lower jaws and tusk like teeth, not unlike an orc or hobgoblin of huge size wrapped in chains of iron. It wears belts of skulls and rotting heads about its throat and waist.","group":"Giant","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Daze","kind":"Ex","details":"Any creature hit by a jack-in-iron's melee attack must succeed on a DC 36 Fortitude save or be dazed 1d2 rounds. The save DC is Strength-based and is a function of the jack-in-irons not its weapon(s)."},{"type":"Pound","kind":"Ex","details":"A jack-in-irons that makes a successful grapple check against a foe two or more sizes smaller than itself can smash the opponent into the ground, walls, nearby trees, or other solid objects as a standard action. This deals 2d6+19 points of bludgeoning damage to the victim. In addition, the opponent must succeed on a DC 36 Fortitude save or be stunned for one round. A jack-in-irons can perform this action once per round as long as it maintains the grapple. The save DC is Strength-based."},{"type":"Shake the Earth","kind":"Ex","details":"As a standard action, a jack-in-irons can stomp its foot on the ground causing powerful vibrations to radiate out around the giant. Any creature within 5 ft. of the jack-in-irons must succeed on a DC 36 Reflex save or fall prone. The save DC is Strength-based."}],"description":"The jacks-in irons enjoy fastening gate chains and portcullis chains around their wrists, fore-arms and shins and tie chains about their throats, shoulders and waists which hang with the heads of their many victims.\n\nJacks-in-irons frequently operate as highwaymen, making their dwellings in ruined towers along abandoned roads. From this base they roam out along old country trails ambushing unwary travelers, trade caravans and the knights assigned to protect them. They are known to take prisoners and hold them for high ransom.\n\nOrcs and goblins often follow a jack-in-irons as their king or leader due to its massive size, brute strength, and penchant for wickedness—all of which are things that such evil creatures admire.\n\nA jack-in-irons stands 20 to 25 ft. tall and weighs 13,000 to 15,000 pounds. It prefers to dress in dark colors such as black or brown and always wears a multitude of chains about its body (as bracelets, necklaces, or slung about its shoulders). Its hair is dark and matted and many male jack-in-irons sport thick, bushy beards. Its eyes are purplish-black with light green irises.\n\nJack-in-irons speak Giant.\n\nBull rush, Awesome blow, bash, bash, bash, cleave, rinse and repeat if necessary until they are out of attacks or out of enemies. Jacks-in-irons think of themselves as invincible and fight to the death.","gear":"spiked greatclub, great chain"},{"name":"Royal Time Elemental","cr":17,"xp":102400,"alignment":"N","size":"Large","type":"outsider","subtypes":["elemental","extraplanar","time"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":27,"ac_touch":21,"ac_flat_footed":21,"ac_mods":"+5 Dex, +1 dodge, +6 insight, +6 natural, -1 size","hp":228,"hd":"24d10+96","hdvalue":24,"fort":14,"ref":21,"will":22,"defensive_abilities":["foresight"],"dr":"15/-","immunities":["elemental traits","temporal magic"],"sr":28,"speed":[{"type":"fly","speed":20,"maneuverability":"perfect"}],"melee":"2 slams +28 (2d6+4 plus cell death)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"alter age","details":"2/day, Fort DC 26"},{"type":"multi-manifestation"},{"type":"temporal displacement","details":"3/day, 24 minutes, Fort DC 26"}],"spell_like_abilities_caster_level":24,"spell_like_abilities_concentration":28,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"summon time elementals","details":"9th level, 1d4 common time elementals, 70%, or 1-2 noble time elementals 30%"},{"spell":"time stop"}]}],"strength":18,"dexterity":20,"constitution":18,"intelligence":22,"wisdom":22,"charisma":20,"baseatk":24,"cmb":29,"cmd":51,"feats":[{"feat":"Cleave"},{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (slam)"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":29},{"skill":"Diplomacy","value":29},{"skill":"Fly","value":38},{"skill":"Intimidate","value":29},{"skill":"Knowledge (arcana)","value":33},{"skill":"Knowledge (history)","value":33},{"skill":"Knowledge (local)","value":33},{"skill":"Knowledge (planes)","value":33},{"skill":"Perception","value":39},{"skill":"Sense Motive","value":33},{"skill":"Stealth","value":28},{"skill":"Survival","value":33}],"languages":["telepathy 100 ft."],"sq":[{"type":"time jaunt","details":"DC 26"}],"environments":["any (Plane of Time)"],"organizations":["solitary","troupe (noble plus 1-2 common time elementals)","court (royal plus 1-2 nobles and 1-4 common time elementals)"],"treasure":"none","description_visual":"This creature appears as a formless cloud of yellowish-red vapor or dust about 5 ft. in diameter.","group":"Elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Alter Age","kind":"Su","details":"Once per day, a noble time elemental can age a creature simply by touching it (this requires a melee touch attack). If successful, the target must succeed on a Fortitude save or advance forward one aging step (from adulthood to middle age, from middle age to old, from old to venerable, and so on). If a character ages, he takes all the effects to his physical ability scores, but doesn't gain any of the bonuses to his mental ability scores. A venerable creature affected by this ability dies (from massive cell death) and cannot be restored to life by mortal magic. The save DC is Constitution-based. Alternately, a time elemental can use its alter age ability to reduce a character's age. If the target is unwilling, the time elemental must succeed on a melee touch attack. An unwilling target can make a Fortitude save to avoid the effects. If the save fails, the target ages one age step backwards (from middle age to adulthood for example) and gains all bonuses to physical ability scores from his new age (simply flip the penalties listed on the aging table into an equal numbered bonus). A character that regresses in age doesn't reduce its mental ability scores. This ability doesn't affect a character that has died from old age. A time elemental can also use this ability to age vegetable matter 10-200 years (older or younger) or mineral matter 100-2,000 years (older or younger). Royal time elementals can use this ability twice per day."},{"type":"Cell Death","kind":"Ex","details":"Damage dealt by a time elemental's slam attack doesn't heal naturally (but it can still be healed magically). Additionally, a creature slain by a time elemental can only be raised through the successful casting of a miracle, true resurrection, or wish spell."},{"type":"Foresight","kind":"Su","details":"A time elemental can see a few seconds into the future. This ability prevents it from being surprised, caught flat-footed, or flanked. It also grants the time elemental an insight bonus to AC equal to its Wisdom bonus. This ability can be negated, but the time elemental can restart it as a free action on its next turn."},{"type":"Immunity to Temporal Magic","kind":"Ex","details":"Time elementals are immune to all time-related spells and effects (including time stop, temporal stasis, and the like). Note, the time stop ability of the noble and royal time elementals can affect those time elementals of lesser power (i.e., a noble can affect a common and a royal can affect a noble or common)."},{"type":"Multi-Manifestation","kind":"Su","details":"A time elemental exists in several other dimensions at any given time. As a standard action, it can bring forth 1d4 of these manifestations to its current locale in order to gain multiple attacks that round. Treat each manifestation as a separate time elemental with hit points equal to the time elemental's current hit points. A manifestation cannot use any of the supernatural or spell-like abilities of the time elemental (a manifestation does however gain the time elemental's foresight ability). A time elemental cannot have more than four manifestations present at one time. Because each manifestation is a part of the time elemental that called them, a successful attack on the time elemental or any of its manifestations deals an equal amount of damage to them all."},{"type":"Summon Time Elementals","kind":"Sp","details":"Once per day, a royal time elemental can attempt to summon 1d4 common time elementals with a 70% chance of success or 1-2 noble time elementals with a 30% chance of success. This ability is the equivalent of a 9th-level spell."},{"type":"Temporal Displacement","kind":"Su","details":"By making a melee touch attack against a foe, a noble or royal time elemental can remove that creature from the current time stream if it fails a Fortitude save. The save is Constitution-based. On a failed save, the creature disappears in a flash of white energy. For a number of minutes equal to the time elemental's Hit Dice, the displaced creature is effectively nonexistent. No form of magic, effect, or force can detect or aid such a creature. A displaced creature can attempt a Wisdom check (DC equal to the initial Fort DC) on its turn to break the effects and end the displacement. The save is Constitution-based. When the effect ends, the creature reappears in the same space it was in before being displaced. If the space is occupied when the creature returns, it is shunted aside to the first open space and takes no damage. A noble or royal time elemental can use this ability three times per day."},{"type":"Time Jaunt","kind":"Su","details":"A time elemental can slip through the time stream and appear anywhere on the same plane of existence as if by greater teleport. This ability transports the time elemental and up to four other creatures within a 30-foot radius. Unwilling creatures can attempt a Will save to avoid being carried away. This ability is otherwise similar to the spell of the same name (caster level equal to the elemental's HD). The save DC is Constitution-based."},{"type":"Time Stop","kind":"Sp","details":"Noble and royal time elementals can create an effect identical to a time stop spell once per day (caster level equals the time elemental's HD)."}],"description":"Time elementals are creatures from a plane most sages are unaware even exists. A time elemental is a powerful creature formed of pure time and matter such as is unknown to even the most learned of sages. It is unknown how or why time elementals enter the Material Plane, as they cannot be summoned using the standard summoning spells. Time elementals attack by forming misty or smoky arms from their forms and lashing at opponents or by spraying a fine mist onto their opponents so as to induce aging. Against particularly powerful opponents, a time elemental uses its alter age ability or (if of the royal sort) summons additional time elementals to its aid.","credit":"The Time Elemental originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Choronzon Demon","cr":18,"xp":153600,"alignment":"CE","size":"Huge","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["confusion (10 ft., DC 24)"],"ac":32,"ac_touch":10,"ac_flat_footed":30,"ac_mods":"+2 Dex, +22 natural, -2 size","hp":290,"hd":"20d10+180","hdvalue":20,"fort":23,"ref":14,"will":10,"dr":"10/cold iron and good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":29,"speed":[{"type":"land","speed":40}],"melee":"bite +30 (2d8+11/19-20), 2 claws +29 (1d8+11 plus daze)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"breath weapon","details":"40-ft. cone, 10d6 damage, Fort DC 29 half, usable every 1d4 rounds"},{"type":"daze","details":"claw attack, Fort DC 31 negates, dazed 1d3 rounds"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":29,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"cause fear"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"true seeing"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 5, 1d4 hezrous, 1d4 nalfeshnees, or 2d4 vrocks 35%"},{"spell":"word of chaos"}]},{"frequency":"3/day","spells":[{"spell":"chaos hammer"},{"spell":"unholy aura"},{"spell":"unholy blight"}]}],"strength":33,"dexterity":15,"constitution":29,"intelligence":12,"wisdom":14,"charisma":18,"baseatk":20,"cmb":33,"cmd":45,"feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":27},{"skill":"Climb","value":34},{"skill":"Escape Artist","value":25},{"skill":"Intimidate","value":27},{"skill":"Perception","value":39},{"skill":"Sense Motive","value":25},{"skill":"Survival","value":22}],"languages":["Abyssal","Celestial","Common","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","band (choronzon plus 6-11 vrocks)"],"treasure":"standard","description_visual":"This creature stands at least 20 ft. tall with a huge, muscular body. Its massive arms and legs end in wicked claws. Its rounded, squat head, sits atop an extremely thick, almost nonexistent neck. The creature's gaping maw is filled with sharp fangs. Two large swept back horns jut from its head just above its rounded eyes.","group":"Demon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Aura of Confusion","kind":"Su","details":"A creature that successfully saves cannot be affected again by that choronzon's aura of confusion for one day. Other demons are immune to the choronzon's aura of confusion. The save DC is Charisma-based."},{"type":"Breath Weapon","kind":"Su","details":"Once every 1d4 rounds, a choronzon can breathe forth a cone of bluish gas in a 40-foot cone. The gas lingers in the area for 1d2 rounds before dispersing. A creature killed by a choronzon's breath weapon has its body break apart into its individual protons, neutrons, and electrons. Creatures killed in this manner can only be restored to life by a miracle, wish, or true resurrection spell. The save DC is Constitution-based."}],"description":"Choronzons are the demons of confusion, dispersion, and ultimate chaos. They are huge behemoths seemingly bred for war and battle, though most rarely take part in the Abyssal wars that rage between the planes. Choronzons prefer to use their talents on weak-minded creatures such as those that inhabit the Material planes, and as such, they are usually encountered there. These demons derive great pleasure in laying waste to villages and towns and even small kingdoms (if the mood strikes them).\n\nAmongst demonkind, choronzons are both feared and hated. A great enmity exists between balors and choronzons that scholars and lorekeepers can document, but cannot determine the source of the hatred between these two demonic races.\n\nA choronzon stands about 20 ft. tall and weighs about 9,000 pounds.\n\nIts scaly flesh is bluish-black and its eyes are crimson. Its horns are darker than the rest of its body and the creature's claws are pitch black. Its teeth are dull ivory in color.\n\nA choronzon begins combat by surrounding itself with its aura of confusion and then unleashing its breath weapon at its foes. Creatures surviving either attack are subjected to its word of chaos. Opponents that continue to press the battle are met with a mix of physical attacks and spell-like abilities. When it uses its Power Attack feat, a choronzon usually takes a -8 penalty on its attack rolls in order to gain a +8 bonus on its damage rolls."},{"name":"Elemental Air Dragon","cr":18,"xp":153600,"alignment":"NE","size":"Huge","type":"outsider","subtypes":["air","elemental","extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":32,"ac_touch":16,"ac_flat_footed":24,"ac_mods":"+8 Dex, +16 natural, -2 size","hp":252,"hd":"24d10+120","hdvalue":24,"fort":13,"ref":22,"will":16,"defensive_abilities":["air mastery"],"dr":"15/magic and silver","immunities":["elemental traits"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":120,"maneuverability":"poor"}],"melee":"bite +31 (2d8+12), 2 claws +31 (2d6+8), 2 wings +28 (1d8+8), tail slap +28 (2d6+12)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"50 ft. cone, DC 29, 10d8 fire"},{"type":"cyclone","details":"30 ft. radius, DC 27, 3d6 bludgeoning"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"control weather"},{"spell":"control winds"}]}],"strength":26,"dexterity":27,"constitution":21,"intelligence":12,"wisdom":15,"charisma":12,"baseatk":24,"cmb":34,"cmd":52,"cmd_special":"+4 vs. trip","feats":[{"feat":"Ability Focus (breath weapon)"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Great Cleave"},{"feat":"Hover"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Snatch"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Fly","value":27},{"skill":"Intimidate","value":28},{"skill":"Knowledge (arcana)","value":28},{"skill":"Knowledge (nature)","value":28},{"skill":"Knowledge (planes)","value":28},{"skill":"Perception","value":29},{"skill":"Survival","value":29}],"languages":["Auran","Common"],"environments":["any (Plane of Air)"],"organizations":["solitary"],"treasure":"double standard","description_visual":"This massive creature resembles a huge dragon composed of air and vapor. Its great wings are translucent and look like wisps of smoke. Its eyes are hollow sockets of mist though a glint of bright sunlight can occasionally be seen dancing across the surface. Its great tail appears as wisps of smoke or vapor and seems to trail off into nothingness.","group":"Elemental Dragon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Air Mastery","kind":"Ex","details":"Airborne creatures take a -1 penalty on attack and damage rolls against an elemental air dragon."},{"type":"Breath Weapon","kind":"Su","details":"An elemental air dragon's breath weapon is a 50 ft. cone of superheated air."},{"type":"Cyclone","kind":"Ex","details":"By beating its wings rapidly back and forth, a hovering elemental air dragon can create a cyclone-like force of wind in a 30-foot radius around its body. This cyclone has the following effects: movement through the cyclone is one-quarter normal, ranged attacks suffer a -8 circumstance penalty in the area, and all nonmagical unprotected flames are automatically extinguished. Large or smaller creatures in the area must succeed on a DC 27 Reflex save or take 3d6 points of bludgeoning damage each round they remain in the area. Medium or smaller creatures in the area must succeed on a second Reflex save (same DC) or be knocked prone and back 1d4 x 10 ft., taking 1d6 points of nonlethal damage per 10 ft. Flying creatures are automatically grounded in this area. The save DC is Constitution-based."}],"description":"The Plane of Air is home to many creatures. Yet none are as feared as the elemental air dragons. Their great form and majestic aura strike fear into the bravest of souls. Elemental air dragons are as evil as their brethren (the other elemental dragons) and take joy and pride in swooping over a settlement or village and destroying it with their great wing buffet. Watching the frightened creatures flee in terror provokes some sort of perverse excitement in these dragons. Luckily, elemental air dragons rarely enter the Material Plane.\n\nElemental air dragons dislike cloud dragons and mist dragons and seek to slay them whenever they are encountered. The average air elemental dragon is 30 ft. long. Elemental air dragons attack by swooping on their prey, unleashing a blast of superheated air, and then flying away. An elemental air dragon rarely, if ever, touches the ground. It often employs its cyclone buffet to knock more powerful creatures prone, then swoops in to blast them with its breath weapon or rend them with its claws and bite."},{"name":"Elemental Water Dragon","cr":18,"xp":153600,"alignment":"NE","size":"Huge","type":"outsider","subtypes":["elemental","extraplanar","water"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":27,"ac_touch":11,"ac_flat_footed":24,"ac_mods":"+3 Dex, +16 natural, -2 size","hp":252,"hd":"24d10+120","hdvalue":24,"fort":13,"ref":17,"will":15,"defensive_abilities":["water mastery"],"dr":"10/magic and silver","immunities":["elemental traits"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":100,"maneuverability":"poor"},{"type":"swim","speed":90}],"melee":"bite +32 (2d8+13), 2 claws +32 (2d6+9), 2 wings +29 (1d8+9), tail slap +29 (2d6+13)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"50 ft. cone, DC 29, 14d8 fire"},{"type":"capsize"},{"type":"drench"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"control water"}]}],"strength":29,"dexterity":16,"constitution":20,"intelligence":10,"wisdom":12,"charisma":10,"baseatk":24,"cmb":35,"cmd":51,"cmd_special":"+4 vs. trip","feats":[{"feat":"Ability Focus (breath weapon)"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Great Cleave"},{"feat":"Hover"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Snatch"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Fly","value":21},{"skill":"Intimidate","value":27},{"skill":"Knowledge (nature)","value":27},{"skill":"Knowledge (planes)","value":27},{"skill":"Perception","value":28},{"skill":"Survival","value":28},{"skill":"Swim","value":21}],"languages":["Aquan","Common"],"sq":[{"type":"transparency"}],"environments":["any (Plane of Water)"],"organizations":["solitary"],"treasure":"double standard","description_visual":"This creature resembles a massive dragon composed entirely of water. Its wings slosh and drip water as it moves them. Its great mouth opens into a maw of inky darkness. Water drips from its fangs.","group":"Elemental Dragon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"The breath weapon of an elemental water dragon is a 50 ft. cone of superheated steam. This breath weapon is effective both on the surface and underwater."},{"type":"Capsize","kind":"Ex","details":"An elemental water dragon can attempt to capsize a boat or ship by ramming it as a charge attack and making a CMB check. The DC of this check is 25, or the result of the boat captain's Profession (sailor) check, whichever is higher. For each size category larger than the elemental water dragon's size, it takes a cumulative -10 penalty on this CMB check."},{"type":"Drench","kind":"Ex","details":"The elemental water dragon's touch puts out torches, campfires, exposed lanterns, and other open flames of nonmagical origin if these are of Large size or smaller. The creature can dispel magical fire it touches as dispel magic (caster level equals elemental's HD)."},{"type":"Water Mastery","kind":"Ex","details":"An elemental water dragon gains a +1 bonus on attack and damage rolls if both it and its foes are touching water. If the opponent or elemental water dragon is touching the ground, the elemental water dragon takes a -4 penalty on attack and damage rolls. (These modifiers are not included in the statistics block.)"},{"type":"Transparency","kind":"Ex","details":"When submerged, an elemental water dragon is effectively invisible (DC 35 Perception check when near the surface only) until it attacks."}],"description":"From the Plane of Water comes the elemental water dragon (also called water wyrm by some sages). They make their homes in the deep oceans of the Material Plane and are rarely found far away from large expanses of water. An elemental water dragon is composed entirely of water and commands respect from the more intelligent sea creatures as well as those humanoids that ply their trade upon the waters. Elemental water dragons are evil and take great pleasure in demanding sacrifice from those that dare enter their realm. If the sacrifice placates the dragon, it lets the creature pass unabated; otherwise, it attacks with all of its might and most often destroys those that offend it or fail to appease its desires.\n\nWater dragons take great pleasure in capsizing and sinking ships. Particularly evil water dragons may accept a sacrifice and then sink the ship of those that crossed its path anyway. On occasion, a group of skum or other evil aquatic creatures can be found allied with an elemental water dragon, but this alliance is usually short-lived and often shaky. It generally ends with the elemental water dragon feeding on its former allies. Elemental water dragons prefer to fight in or near water where they can use their transparency and water mastery abilities to full advantage. They prefer to attack from ambush, often lying in wait for their opponents and then springing from the waves to assault their foes."},{"name":"Ghaggurath","cr":18,"xp":153600,"alignment":"N","size":"Huge","type":"aberration","init":5,"senses":[{"type":"all-around vision"},{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":31,"ac_touch":13,"ac_flat_footed":26,"ac_mods":"+5 Dex, +18 natural, -2 size","hp":304,"hd":"21d8+210","hdvalue":21,"fort":19,"ref":12,"will":20,"defensive_abilities":["resistant to poison"],"dr":"15/-","immunities":["charm","fear","paralysis","sleep"],"resists":[{"type":"acid","value":20},{"type":"cold","value":20},{"type":"fire","value":20},{"type":"sonic","value":20}],"sr":29,"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"8 bites +27 (2d6+13/19-20 plus grab)","ranged":"4 thrall worms +18 (1d8 plus poison)","space":"15 ft.","reach":"15 ft. (30 ft. with tentacle)","special_attacks":[{"type":"thrall"}],"strength":37,"dexterity":21,"constitution":30,"intelligence":24,"wisdom":22,"charisma":21,"baseatk":15,"cmb":30,"cmb_special":"+4 vs. grapple","cmd":45,"cmd_special":"can't be tripped","feats":[{"feat":"Bleeding Critical"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (bite)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":26},{"skill":"Climb","value":45},{"skill":"Escape Artist","value":29},{"skill":"Intimidate","value":29},{"skill":"Knowledge (any)","value":31},{"skill":"Knowledge (history)","value":28},{"skill":"Knowledge (planes)","value":28},{"skill":"Perception","value":36},{"skill":"Sense Motive","value":27},{"skill":"Stealth","value":21},{"skill":"Survival","value":30},{"skill":"Swim","value":22}],"languages":["Abyssal","Common","Giant","Goblin","Infernal","Terran","Undercommon","telepathy 100 ft."],"environments":["any underground"],"organizations":["solitary"],"treasure":"double standard","description_visual":"This massive creature appears to be a pile of brownish-gray flesh covered in large eyes. Eight long tentacles sprout from its body, each ending in a mouth lined with sharpened fangs. Its large central mass is amoeba-like and oozes a foul-smelling liquid.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Thrall worm-injury; save DC 30 Fort; frequency 1/round for 6 rounds; effect 1d6 Wisdom damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Resistance to Poison","kind":"Ex","details":"A ghaggurath is highly resistant to poison. Whenever it makes a saving throw against poison, it can roll its save twice, keeping the better result."},{"type":"Spittle","kind":"Ex","details":"In lieu of biting, a tentacle mouth can eject a fleshy worm, called a thrall worm, at a single target to a range of 50 ft. A target that is hit is automatically bitten by the worm and subjected to the ghaggurath's poison. Regardless of which head fires the worm, a ghaggurath can launch only 24 such worms in any 24-hour period. When a thrall worm strikes its target, it quickly burrows into the target's body. This worm can be safely removed with a successful DC 30 Heal check or by the application of a cure spell; otherwise removing the worm deals an extra 1d6 points of damage to the target. After 1d4 rounds, the worm works its way so deep into the target's body that it can only be removed by cutting open the area (dealing 1d8 points of damage to the victim) before attempting a Heal check or casting a cure spell. A remove disease spell destroys the worm if the caster succeeds on a caster level check against DC 30. As long as a thrall worm remains inside a target, the target cannot heal the Wisdom damage dealt by the ghaggurath's poison. A creature can only ever have one thrall worm inside it at one time; it can however be attacked by and bitten by multiple thrall worms. The check DCs are Constitution-based."},{"type":"Thrall","kind":"Su","details":"A victim whose Wisdom score drops to 0 from the ghaggurath's poison is automatically dominated (as by a dominate monster spell, CL 20th). This effect lasts until the thrall worm is removed and at least 1 point of Wisdom is restored. The ghaggurath doesn't have to concentrate each day to maintain this effect, and a dominated creature doesn't receive a save to break the effects. If the ghaggurath is slain, any thrall under its command fall unconscious and remain so until the thrall worm is removed and at least 1 point of Wisdom is restored."}],"description":"The ghaggurath is a massive subterranean creature feared for its ability to enslave others to its will, and feared for its ability to devour just about anything it desires. Though the ghaggurath has a seemingly endless hunger, it can in fact go up to 6 months without a meal; its body enters a sort of hibernation to sustain the creature. During this time, many creatures assume the ghaggurath is vulnerable; it isn't. Though the creature appears to be hibernating, it is completely aware of its surroundings. Many would-be predators and foolish adventurers have stumbled upon a hibernating ghaggurath assuming it unaware, only to become the creature's next meal.\n\nResourceful adventurers who have braved the subterranean worlds tell of huge cities governed by ghagguraths and whose entire populations are enslaved and under command of these creatures. Other tales speak of an underground race of humans that worship the ghaggurath as deities. Most subterranean races fear these creatures and avoid them at all costs.\n\nIn combat, a ghaggurath lashes out with its tentacles, the mouths biting and gnashing its opponents. A grabbed foe is held and subjected to multiple bites. Stronger opponents, particularly spellcasters, are of great interest to a ghaggurath, and it usually subjects such opponents to its thrall worms, attempting to bring them under its control. Controlled spellcasters are forced to do the ghaggurath's bidding or carried back to their great underground cities, enslaved, and experimented upon. Eventually, when a ghaggurath grows weary of the creature, it devours it."},{"name":"Great Wyrm Gray Dragon","cr":18,"xp":153600,"alignment":"NE","size":"Gargantuan","type":"dragon","init":3,"senses":[{"type":"dragon senses"},{"type":"smoke vision"}],"auras":["frightful presence (360 ft., DC 27)"],"ac":42,"ac_touch":5,"ac_flat_footed":42,"ac_mods":"-1 Dex, +37 natural, -4 size","hp":362,"hd":"25d12+200","hdvalue":25,"fort":22,"ref":15,"will":22,"dr":"20/magic","immunities":["fire","paralysis","sleep"],"sr":29,"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":60},{"type":"fly","speed":250,"maneuverability":"average"},{"type":"swim","speed":40}],"melee":"2 claws +34 (2d6+13), bite +35 (2d8+19/19-20), 2 wings +32 (2d6+6), tail slap +32 (2d8+19)","space":"20 ft.","reach":"15 ft. (20 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"120-ft. line, 24d6 fire; DC 30 Ref half"},{"type":"pyroclast"}],"spell_like_abilities_caster_level":25,"spell_like_abilities_concentration":33,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"ash storm"},{"spell":"burning hands"},{"spell":"pyrotechnic eruption"},{"spell":"pyrotechnics"},{"spell":"scorching ash form"},{"spell":"steal breath"}]}],"spellsknown_caster_level":15,"spellsknown_concentration":23,"spellsknown":[{"spell_level":8,"spell_slots":4,"spells":[{"spell":"horrid wilting"},{"spell":"moment of prescience"}]},{"spell_level":7,"spell_slots":6,"spells":[{"spell":"limited wish"},{"spell":"power word blind"},{"spell":"waves of exhaustion"}]},{"spell_level":6,"spell_slots":6,"spells":[{"spell":"flesh to stone"},{"spell":"greater heroism"},{"spell":"move earth"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"cloudkill"},{"spell":"telekinesis"},{"spell":"transmute rock to mud"},{"spell":"wall of stone"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"dimension door"},{"spell":"greater invisibility"},{"spell":"scrying"},{"spell":"stoneskin"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"dispel magic"},{"spell":"gaseous form"},{"spell":"protection from energy"},{"spell":"ray of exhaustion"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blur"},{"spell":"eagle's splendor"},{"spell":"gust of wind"},{"spell":"locate object"},{"spell":"mirror image"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"burning hands"},{"spell":"magic missile"},{"spell":"protection from good"},{"spell":"obscuring mist"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"ray of frost"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"touch of fatigue"}]}],"strength":37,"dexterity":8,"constitution":27,"intelligence":21,"wisdom":23,"charisma":21,"baseatk":25,"cmb":42,"cmd":51,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Great Cleave"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":33},{"skill":"Fly","value":21},{"skill":"Intimidate","value":33},{"skill":"Knowledge (arcana)","value":33},{"skill":"Knowledge (local)","value":33},{"skill":"Knowledge (nature)","value":33},{"skill":"Perception","value":38},{"skill":"Sense Motive","value":38},{"skill":"Spellcraft","value":33},{"skill":"Stealth","value":15},{"skill":"Swim","value":49},{"skill":"Use Magic Device","value":33}],"languages":["Abyssal","Aquan","Common","Draconic","Giant","Infernal Special Abilities"],"sq":[{"type":"adaptive breathing"},{"type":"smoke form"}],"environments":["warm coastlines"],"organizations":["solitary"],"treasure":"triple standard","description_visual":"Steam emanates from the nostrils and mouth of this slate gray dragon.","group":"Dragon","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Adaptive Breathing","kind":"Ex","details":"A gray dragon does not require respiration, and is immune to effects that require breathing (such as inhaled poison). This ability does not grant immunity to cloud or gas attacks that do not require breathing."},{"type":"Breath Weapon","kind":"Su","details":"A gray dragon's breath weapon is a superheated line of steam."},{"type":"Change Shape","kind":"Su","details":"A young or older gray dragon can take any animal or humanoid form 3/day as if using polymorph."},{"type":"Pyroclast","kind":"Su","details":"An old or older gray dragon can use its breath weapon to create a cloud of volcanic smoke and ash as a standard action that deals fire damage equal to the dragon's hit dice to any creature inside it. The cloud moves with the dragon and has a radius of 20 feet and lasts 3d4 rounds. Any creature that starts its turn inside the cloud takes damage, but can make a Reflex save for half. A strong wind, such as that created by a gust of wind, disperses the cloud in 1 round."},{"type":"Smoke Form","kind":"Ex","details":"An ancient or older gray dragon can assume a smoky form as a move action, once per day. It can spend up to 1 minute per day per HD in smoke form. This time does not have to be consecutive, but it must be spent in 1-minute increments. A smoke form dragon can fly at its normal fly speed (but good maneuverability). The ability is otherwise similar to a gaseous form spell."},{"type":"Smoke Vision","kind":"Ex","details":"A very young gray dragon can see perfectly in smoky conditions (such as those created by pyrotechnics)."},{"type":"Sooty Breath Weapon","kind":"Su","details":"Living creatures that fail their saves against the gray dragon's breath weapon are tormented by burning eyes. This effect imposes a -4 penalty to AC and a -2 penalty on attack rolls for 2d4 rounds."}],"description":"Gray dragons are evil dragons that inhabit mountains and hills near coastlines. They have little regard for other races and often enslave others to do their bidding. Adult and older gray dragons are rarely found without a retinue of humanoid slaves. Gray dragons mate for life and a single mated pair often terrorizes nearby villages, laying waste to those that oppose the dragon's will."},{"name":"Requiem Beetle","cr":18,"xp":153600,"alignment":"N","size":"Gargantuan","type":"vermin","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"100 ft."}],"ac":31,"ac_touch":7,"ac_flat_footed":30,"ac_mods":"+1 Dex, +24 natural, -4 size","hp":345,"hd":"30d8+210","hdvalue":30,"fort":24,"ref":11,"will":10,"dr":"10/-","immunities":["acid","mind-affecting effects"],"speed":[{"type":"land","speed":50}],"melee":"2 claws +29 (2d8+11 plus grab), bite +29 (2d10+11)","space":"20 ft.","reach":"15 ft.","special_attacks":[{"type":"constrict","details":"4d6+11"},{"type":"earth-shaking"},{"type":"trample","details":"2d8+16, DC 36"}],"strength":33,"dexterity":12,"constitution":24,"wisdom":11,"charisma":2,"baseatk":22,"cmb":37,"cmb_special":"+4 vs. grapple","cmd":48,"feats":[{"feat":"Cleave","type":"bonus"},{"feat":"Power Attack","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":1,"special":"(+9 jump) Perception +8"}],"environments":["any underground","warm mountains"],"organizations":["solitary"],"treasure":"none","description_visual":"This massive beetle has a dark red carapace, blackish-red wing covers, and black legs. Two large claw-like pincers protrude from its front slashing and ripping the very air around the creature. Its oversized mandibles are dark reddish-black.","group":"Beetle","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Earth-Shaking","kind":"Ex","details":": Whenever a requiem beetle moves more than 10 ft. in a round, all creatures within 10 ft. of the requiem beetle must succeed on a DC 34 Reflex save or fall prone. The save DC is Strength-based."}],"description":"Requiem beetles are beetles of enormous size reaching lengths of 100 ft. or more. They make their lairs in remote mountainous regions or deep underground in massive caverns. A typical lair contains a solitary creature (no two have ever been encountered together). Mating and reproduction rituals and methods among requiem beetles are unknown to sages, though it is generally accepted that requiem beetles follow other similar beetle and vermin mating patterns.\n\nThese monsters sustain themselves on a diet of mosses, funguses, lichens, molds, and oozes. Their natural immunity to acid allows them to kill and digest most oozes without bother. Requiem beetles are mindless hunters, like other vermin, and simply kill and eat whatever they come across. When they deplete an area of its food source they simply move to another location.\n\nRequiem beetles measure about 40 ft. long and weigh about 18 tons.\n\nA requiem beetle charges into combat attempting to trample as many of its opponents as it can. It uses its massive pincers in battle to cut and tear its opponents or grab and squeeze them. Once a requiem beetle grabs a foe it rarely lets go until either it or the opponent is dead. If forced to flee, a requiem beetle doesn't release its prey, but instead, carries it off with it."},{"name":"Slorath","cr":18,"xp":153600,"alignment":"CE","size":"Gargantuan","type":"magical beast","subtypes":["cold"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":25,"ac_touch":9,"ac_flat_footed":22,"ac_mods":"+3 Dex, +16 natural, -4 size","hp":250,"hd":"20d10+140","hdvalue":20,"fort":19,"ref":17,"will":10,"immunities":["cold"],"sr":32,"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":10}],"melee":"bite +26 (2d8+15)","ranged":"paralysis ray +20 (paralysis)","space":"20 ft.","reach":"15 ft.","special_attacks":[{"type":"paralyzing gaze"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"glacial storm","details":"as meteor storm, but deals cold damage; half"}]},{"frequency":"3/day","spells":[{"spell":"cone of cold"},{"spell":"freezing sphere","details":"half"},{"spell":"ice storm"}]}],"strength":31,"dexterity":17,"constitution":24,"intelligence":14,"wisdom":14,"charisma":15,"baseatk":20,"cmb":34,"cmd":47,"cmd_special":"can't be tripped","feats":[{"feat":"Awesome Blow"},{"feat":"Gaze to Ray"},{"feat":"Improved Initiative"},{"feat":"Improved Bull Rush"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (ray)"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Climb","value":20},{"skill":"Perception","value":26},{"skill":"Spellcraft","value":22},{"skill":"Stealth","value":14,"special":"+24 in arctic environments"},{"skill":"Swim","value":20}],"languages":["Common","Draconic","Giant"],"environments":["cold hills","cold mountains"],"organizations":["solitary"],"treasure":"standard","description_visual":"Slithering from the snow emerges a 40-foot long serpent with glossy-white scales and a bluish-white underbelly, its long, slender, icy-blue tongue flickering. Its vertical-slit pupils glow an otherworldly greenish-blue and rows of sharpened teeth line tremendous mouth.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Paralyzing Gaze","kind":"Su","details":"Paralysis 1d6 +4 rounds, 30 ft., Fortitude DC 22 negates. The save is Charisma-based."},{"type":"Paralysis","kind":"Su","details":"Alternately, a slorath can use its Gaze to Ray feat to release a ray of paralysis (range of 30 ft.) as a ranged touch attack. After using its gaze attack in this manner, the slorath cannot use its paralyzing gaze for 1d4 rounds and it is disoriented during this time (-2 penalty on attack rolls, saves, skill checks, and ability checks). The save is Charisma-based."}],"description":"The great sloraths are found only in the coldest and most desolate regions, though close enough to civilization to hunt and stage raids against humanoid settlements when the slorath goes hunting. Highly intelligent and aware, the slorath is a fierce predator that defends its hunting ground with precision tactics and power. Small villages within a slorath's territory sometimes strike deals with these creatures; offering sacrifices in return for the protection the slorath can offer.\n\nSlorath are generally nocturnal carnivores. They exist on a diet of white dragons, polar bears, frost men (see entry in this book), and barbegazi (see entry in this book). They are particularly fond of white dragon meat and often go out of their way to hunt for such creatures. Frost giants often strike deals with frost giants so it isn't uncommon for the two to be encountered together working toward a common goal.\n\nSlorath lairs are either enormous tunnels deep under the ice and snow or abandoned white dragon lairs. Encounters are almost always with a solitary creature. In rare instances young sloraths or eggs might be found in a lair. Young slorath resemble their parent in all respects. Slorath eggs are stark white in color.\n\nA slorath usually begins an encounter by hiding under the snow waiting for prey to wander by, or by lying unmoving on the snow itself where its coloration offers it camouflage against the white background. When prey comes within range, the slorath assaults it with its paralyzing gaze.\n\nHelpless creatures are then attacked with its powerful bite. Those that attempt to avoid its gaze witness the slorath project its gaze as a ray of blue energy (using the Gaze to Ray feat).\n\nContinued aggression against a slorath results in it unleashing a cone of cold or ice storm on its foes. If faced with particularly powerful foes, it uses its ice storm and glacial storm special abilities. A slorath doesn't fight to the death and flees if combat goes against it. Note however, if young slorath are present and they are threatened, a slorath fights to the death."},{"name":"Demoriel","cr":19,"xp":204800,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect magic"},{"type":"see invisibility"}],"ac":40,"ac_touch":25,"ac_flat_footed":35,"ac_mods":"+5 Dex, +15 natural, +10 profane","hp":210,"hd":"20d10+100","hdvalue":20,"hp_mods":["regeneration 5 (good, silver)"],"fort":11,"ref":17,"will":6,"save_mods":"+2 on all saves from spells and effects from good-aligned creatures","defensive_abilities":["resistant to good magic"],"dr":"15/good and silver","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":30,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"+3 unholy short sword +30 (1d6+9/19- 20) or 2 claws +26 (1d6+6)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"enrapture"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":25,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"},{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"blasphemy"},{"spell":"charm monster"},{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"},{"spell":"hold monster"},{"spell":"invisibility","details":"self only"},{"spell":"magic circle against good"},{"spell":"major image"},{"spell":"polymorph","details":"self only"},{"spell":"suggestion"},{"spell":"unholy aura"}]},{"frequency":"1/day","spells":[{"spell":"meteor swarm"},{"spell":"power word stun"}]},{"frequency":"3/day","spells":[{"spell":"summon","details":"level 9, 1d6 erinyes or 1d2 barbed devils 100% or 1 horned devil 60%"},{"spell":"wall of fire"}]}],"strength":23,"dexterity":21,"constitution":20,"intelligence":23,"wisdom":23,"charisma":31,"baseatk":20,"cmb":12,"cmd":27,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Deceitful"},{"feat":"Great Cleave"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Persuasive"},{"feat":"Quicken Spell-Like Ability (fireball)"},{"feat":"Power Attack"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Bluff","value":45},{"skill":"Diplomacy","value":45},{"skill":"Disguise","value":37},{"skill":"Fly","value":28},{"skill":"Intimidate","value":37},{"skill":"Knowledge (arcana)","value":29},{"skill":"Knowledge (planes)","value":29},{"skill":"Knowledge (religion)","value":26},{"skill":"Perception","value":33},{"skill":"Sense Motive","value":33},{"skill":"Stealth","value":28},{"skill":"Survival","value":26}],"languages":["Abyssal","Celestial","Common","Draconic","Giant","Ignan","Infernal","telepathy 100 ft."],"environments":["any (Infernus)"],"organizations":["solitary","troupe (Demoriel plus 1-4 horned devils)"],"treasure":"double standard","description_visual":"This creature is a very attractive female with raven black hair, coal black eyes, amber skin, and a shapely form. Small bat wings protrude from her shoulders, and tiny horns jut from her forehead, just above her eyes.","group":"Devil","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Enrapture","kind":"Su","details":"Those viewing Demoriel must succeed on a DC 30 Will save or stand enthralled for 1 minute. This functions as a hold person spell (caster level 20th). An affected creature can attempt a new Will save each round to break the effects. The save DC is Charisma-based. A creature that successfully saves cannot be affected by Demoriel's enrapture for one day. Reaver: Reaver is Demoriel's finely crafted +3 unholy short sword."}],"description":"Demoriel was once a powerful angel that made her home in the heavens among the other angels. In the Celestial Hierarchy she was a member of the Cherubim and served alongside Gabriel, Raphael, and Ophaniel. During the Unholy Schism, she sided with Lucifer and aided him by seducing another Cherub wherein Lucifer caught the angel unaware and murdered him on the spot. When Lucifer was thrown down from the good-aligned planes, Demoriel was beside him; cast out for the sin of slaying another angel and spilling the blood of an angel in the outer planes.\n\nWhen Lucifer envisioned Hell, Demoriel envisioned herself on the throne next to him, serving as Hell's Queen. Unfortunately for her, she became one of his many concubines but never his bride, for the Great Uprising occurred in Hell and the other arch-devils moved to destroy Lucifer and his court. When Lucifer was removed from Hell's Throne and took up residence in a pocket plane called Infernus, Demoriel followed. Once again, she was denied her place on the throne next to Lucifer as he took a devil named Shabiri as his consort. Though Demoriel remains ever loyal to Lucifer, she doesn't trust nor like Shabiri. For now she waits until her time comes when she can discredit or destroy Shabiri and replace her as Lucifer's consort.\n\nThough Lucifer no longer rules Hell, Demoriel still serves him unswervingly. She follows no other, though she is more than willing to lead other creatures to their demise by feigning loyalty to them. She has a particularly vile hatred for celestials (more than other devils do it seems) and enjoys corrupting and destroying them. Demoriel attacks with her spell-like abilities, attempting to charm the strongest opponents she faces. If forced into melee, she attacks with her spell-like abilities and short sword or summons other devils to fight for her while she maintains a position away from the immediate fight.","gear":"Reaver"},{"name":"Leviathan","cr":19,"xp":204800,"alignment":"N","size":"Colossal","type":"magical beast","init":-2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":30,"ac_touch":0,"ac_flat_footed":30,"ac_mods":"-2 Dex, +30 natural, -8 size","hp":310,"hd":"20d10+200","hdvalue":20,"fort":24,"ref":10,"will":12,"dr":"20/magic","immunities":["cold","electricity"],"resists":[{"type":"fire","value":20},{"type":"sonic","value":20}],"sr":30,"speed":[{"type":"swim","speed":60}],"melee":"bite +34 (6d6+22/19-20), tail slap +29 (4d6+11)","space":"30 ft.","reach":"20 ft.","special_attacks":[{"type":"capsize"},{"type":"smashing breach"},{"type":"swallow whole","details":"6d8+22 acid damage, AC 25, 31 hp"},{"type":"tail storm"},{"type":"whale song"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":30,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"control weather"},{"spell":"summon nature's ally IX","details":"aquatic animals only"}]}],"strength":54,"dexterity":6,"constitution":30,"intelligence":18,"wisdom":18,"charisma":21,"baseatk":20,"cmb":50,"cmd":58,"cmd_special":"can't be tripped","feats":[{"feat":"Augment Summoning","type":"bonus"},{"feat":"Critical Focus"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Swim)"},{"feat":"Staggering Critical"}],"skills":[{"skill":"Knowledge (any one)","value":24},{"skill":"Knowledge (local)","value":24},{"skill":"Knowledge (nature)","value":24},{"skill":"Perception","value":27},{"skill":"Stealth","value":5},{"skill":"Swim","value":59}],"languages":["Aquan"],"sq":[{"type":"hold breath"}],"environments":["any oceans"],"organizations":["solitary"],"treasure":"standard","description_visual":"This is a tremendous sea creature, resembling a whale of gigantic proportions. Its humped back stands like a mountain, and its massive eye is nearly as large as a sailing ship. Its cavernous blowhole spews forth a jet of water like a cyclone.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Smashing Breach","kind":"Ex","details":"As a full-round action, a leviathan can make a special charge attack against creatures on the surface of the water. At the end of its charge, the leviathan breaches, then slams down onto the target with incredible force. Any Huge or smaller creatures in the leviathan's space must make a DC 30 Reflex save or take 4d8+33 points of bludgeoning damage and be forced into the nearest square that is adjacent to the whale. This breach automatically attempts to capsize any boats caught wholly or partially in this area. The save DC is Constitution-based."},{"type":"Tail Storm","kind":"Ex","details":"As a full-round action, a leviathan can raise its massive tail and bring it crashing down into the water, causing a massive wave that sinks ships in the area. The resulting wave fans out from the leviathan's tail in a 100-foot cone. Huge or smaller ships caught in the area and within 10 ft. of the leviathan's tail automatically sink. Creatures in the water and within 10 ft. of the leviathan's tail take 4d6+22 points bludgeoning damage. A successful DC 42 Reflex save reduces the damage by half. Additionally, a creature that fails its save is pushed 6d6 x 10 ft. away. Huge or smaller ships more than 10 ft. away within the area must succeed on a Profession (sailor) check or capsize. The DC of this check is 42, decreasing by 5 for every 10 ft. from the leviathan a ship is. The DC increases by a cumulative +5 for each size smaller than Huge a ship is. The save and base check DC is Strength-based."},{"type":"Whale Song","kind":"Su","details":"As a swift action, a leviathan can unleash a song that is so deep and of such low frequency that the vibrations alone have adverse effects on living creatures. Any living creature within 100 ft. of a singing leviathan must succeed on a DC 30 Fortitude save or be stunned for 1d6 rounds. A creature that succeeds on its save is unaffected by that leviathan's whale song for one day. This song is more felt than heard, and can be detected by creatures up to 10 miles away. Creatures capable of detecting extremely low-frequency sounds (e.g. dolphins, whales, other leviathans) can detect this song up to 100 miles away. The save DC is Constitution-based."}],"description":"Legend holds that there is but one leviathan in every ocean in the world, each creature being the undisputed sovereign of its domain. Smaller leviathans control the seas, whilst the tiniest-still massive by any measure-lurk in a few secluded bays within the lonelier parts of the world. Completely unopposed by any other creature, they dominate their realms. When a leviathan grows to such size that it can no longer be supported by its territory, it challenges another larger in size, seeking to gain mastery of its sea or ocean. Failure in this challenge results in death but if it overcomes its rival, the leviathan assumes sovereignty of the domain. Battles between these titanic creatures are an awesome sight to behold, for tidal waves and hurricanes erupt, devastating nearby coastal settlements.\n\nLeviathans are over 500 ft. long and weigh many hundreds of tons.\n\nLeviathans are seldom stirred to anger and only attack to defend themselves from opponents who can truly harm them—a rare occurrence indeed. They strike with their massive tail or by biting. A leviathan is so immense that it cannot bite any creature smaller than Huge; such small prey is simply swallowed whole. Any enemy flanking a leviathan from behind is attacked with a devastating tail slap or subjected to the leviathan's tail storm attack."},{"name":"Amalgamation","cr":20,"xp":307200,"alignment":"N","size":"Gargantuan","type":"construct","init":9,"senses":[{"type":"blindsight","modifier":"100 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":25,"ac_touch":25,"ac_flat_footed":16,"ac_mods":"+10 deflection, +9 Dex, -4 size","hp":225,"hd":"30d10+60","hdvalue":30,"fort":10,"ref":19,"will":15,"dr":"10/-","immunities":["construct traits (+60 hp)","magic"],"speed":[{"type":"land","speed":10},{"type":"fly","speed":50,"maneuverability":"perfect"}],"melee":"varies +33 (damage by weapon)","ranged":"varies +35 (damage by weapon)","space":"20 ft.","reach":"15 ft.","special_attacks":[{"type":"multiple attacks"},{"type":"swarm attack","details":"10d6"}],"strength":24,"dexterity":28,"wisdom":20,"charisma":1,"baseatk":30,"cmb":41,"cmd":60,"sq":[{"type":"item use"}],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard (varies with individual Amalgamation)","description_visual":"A large collection of items rises up, forming into a swirling chaos that is the body of this being. The items move about throughout its bulk, somehow not touching one another in their mad dance.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Item Use","kind":"Su","details":"The amalgamation can use any of the items contained within its bulk. When activating magic items, it is considered to be using them as if a person of the required class, with a 20 in any relevant ability scores (or its natural scores, whichever are better). Furthermore, because of its innate magical nature, the save DC against any effects produced by magic items is 2 greater than normal. Finally, it can wield weapons and items as if it were of the appropriate size class for their type, so it suffers no hit penalties for being a Gargantuan construct with such items. Unless instructed otherwise, the amalgamation uses items at random from its bulk. However, it doesn't target them randomly—it uses them with care and precision, as if it had 18 Intelligence. Items with limited uses, such as scrolls and wands, are expended normally."},{"type":"Multiple Attacks","kind":"Ex","details":"The amalgamation can activate and use up to five items per round. It can therefore attack with weapons, activate magic items, hurl alchemical items like thunderstones, or slam random objects against opponents."},{"type":"Swarm Attack","kind":"Ex","details":"The amalgamation can move over enemies and damage them with the flying weapons and objects composing its bulk. It does this simply by moving over its victims, who are allowed either a DC 34 Reflex save or an attack of opportunity against the amalgamation, at their option. Anyone who begins their turn engulfed by the amalgamation takes 10d6 points of damage per round, with a DC 34 Reflex save allowed for half. This isn't considered an area effect for the purposes of evasion and similar abilities. The damage inflicted by the amalgamation overcomes all forms of damage reduction except epic. The save DC for both Reflex saves is Dexterity-based. Further, this damage is considered continuous for the purposes of determining if it disrupts spellcasting, concentration and the like."},{"type":"Immunity to Magic","kind":"Ex","details":"The amalgamation is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted: Dispel magic and greater dispel magic can be used to deactivate magic items, as per a targeted item dispel. Mage's disjunction causes it to subside into quiescence for 1d4+1 rounds, during which time it is considered helpless."}],"description":"The amalgamation is a special creation used by certain ancient spellcasters to defend their hordes and treasure vaults-for even should the guardian fall, most of the items being guarded would be destroyed, and hence not fall into enemy hands. The creature is composed of a large number of magical and mundane items, and it can use any of them to attack. Because of its magical nature, the amalgamation can even wield magic items such as wands without penalty. The amalgamation resembles a vortex or cloud of items 20 ft. in diameter, swirling within a shimmering field of energy. The precise appearance of the construct depends on the items that comprise its bulk.","credit":"Originally appearing in Rappan Athuk Reloaded (© Necromancer Games, 2006)"},{"name":"Elemental Earth Dragon","cr":20,"xp":307200,"alignment":"NE","size":"Huge","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":26,"ac_touch":8,"ac_flat_footed":26,"ac_mods":"+18 natural, -2 size","hp":252,"hd":"24d10+120","hdvalue":24,"fort":13,"ref":14,"will":15,"defensive_abilities":["earth mastery"],"dr":"10/magic and cold iron","immunities":["elemental traits"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":100,"maneuverability":"poor"},{"type":"burrow","speed":20}],"melee":"bite +35 (2d8+18), 2 claws +35 (2d6+12), 2 wings +32 (1d8+12), tail slap +32 (2d6+18)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"50 ft. cone, DC 29, 14d8 fire and slashing"}],"strength":35,"dexterity":10,"constitution":20,"intelligence":10,"wisdom":12,"charisma":10,"baseatk":24,"cmb":38,"cmd":48,"cmd_special":"+4 vs. trip","feats":[{"feat":"Ability Focus (breath weapon)"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Great Cleave"},{"feat":"Hover"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Snatch"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Fly","value":19},{"skill":"Intimidate","value":27},{"skill":"Knowledge (nature)","value":27},{"skill":"Knowledge (planes)","value":27},{"skill":"Perception","value":28},{"skill":"Survival","value":28}],"languages":["Common","Terran"],"sq":[{"type":"assimilation"},{"type":"freeze"},{"type":"meld with stone"}],"environments":["any (Plane of Earth)"],"organizations":["solitary"],"treasure":"double standard","description_visual":"This creature resembles a 30-foot long dragon composed of stone and earth. Its great wings glisten like polished stone. Its eyes are deep gray and its roar seems to shake the very earth itself.","group":"Elemental Dragon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Assimilation","kind":"Su","details":"When an elemental earth dragon slays an opponent, it dehydrates the flesh with its breath weapon and pulverizes the bones. The residue is then absorbed into the dragon's body. An assimilated creature can only be restored to life using wish, miracle, or true resurrection, but even then, there is a 50% chance that such powerful magic fails."},{"type":"Breath Weapon","kind":"Su","details":"An elemental earth dragon's breath weapon is a 50 ft. cone of scorching sand and gravel."},{"type":"Earth Mastery","kind":"Ex","details":"An elemental earth dragon gains a +1 bonus on attack and damage rolls if both it and its foes are touching the ground. If an opponent is airborne or waterborne, the elemental earth dragon takes a -4 penalty on attack and damage rolls. (These modifiers are not included in the stat block.)"},{"type":"Freeze","kind":"Ex","details":"An elemental earth dragon can hold itself so still it appears to be a statue. An observer must succeed on a DC 20 Perception check to notice that the elemental earth dragon is really alive."},{"type":"Meld into Stone","kind":"Ex","details":"An elemental earth dragon can meld its body with any stone surface large enough to accommodate its entire body. This is a standard action and has an unlimited duration (the dragon can stay melded as long as it desires). It otherwise resembles the meld into stone spell (caster level 20th)."}],"description":"Elemental earth dragons are the strongest of the elemental dragons. Using their great stone tail or earthen claws, they can destroy almost anything in short order. The majority of their time is spent burrowing through the Plane of Earth devouring gems, minerals, and silicate life forms. On occasion, they are summoned to the Material Plane by evil (and foolish) spellcasters who usually live just long enough to regret their mistake. Elemental earth dragons are evil (perhaps the most evil of the elemental dragons in addition to being the strongest) and despise most other forms of life. They rarely associate with other creatures, though a few have been known to have dealings with the occasional earth elemental.\n\nElemental earth dragons cannot enter water; they must burrow under it or walk around it. The average elemental earth dragon is 30 ft. long. Its roar can be heard up to 5 miles away. Elemental earth dragons prefer to attack from ambush and secret rather than using a direct frontal assault. An elemental earth dragon lies in wait using its freeze ability or meld into stone ability and springs to attack when its prey comes into range. They are also fond of burrowing into the ground and surfacing under their prey, thereby gaining total surprise. Slain opponents are processed and absorbed into the body of the elemental earth dragon."},{"name":"Mortuary Cyclone","cr":20,"xp":307200,"alignment":"N","size":"Huge","type":"undead","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["desecrating aura (50 ft.)"],"ac":28,"ac_touch":13,"ac_flat_footed":27,"ac_mods":"+1 Dex, +15 natural, +4 profane, -2 size","hp":263,"hd":"31d8+124","hdvalue":31,"fort":20,"ref":17,"will":24,"dr":"15/bludgeoning and magic","immunities":["undead traits"],"sr":31,"speed":[{"type":"land","speed":40}],"melee":"slam +33 (2d8+16/19-20 plus energy drain)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"create spawn"},{"type":"energy drain","details":"2 levels, DC 29"},{"type":"necrocone"},{"type":"whirlwind","details":"10-40 ft. high, 3d6 damage, DC 36"}],"strength":33,"dexterity":12,"intelligence":11,"wisdom":12,"charisma":19,"baseatk":23,"cmb":36,"cmd":49,"feats":[{"feat":"Ability Focus (energy drain)"},{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Great Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (slam)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Intimidate)"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Acrobatics","value":32},{"skill":"Intimidate","value":46},{"skill":"Perception","value":39},{"skill":"Sense Motive","value":1},{"skill":"Stealth","value":27}],"languages":["Common (cannot speak)"],"sq":[{"type":"unholy grace"}],"environments":["any land"],"organizations":["solitary","band (10-40 HD of undead creatures)"],"treasure":"none","description_visual":"A whirling and spinning cyclone of dirt, bone fragments, and body parts rapidly advances toward you. It stands about 20 ft. tall. From its central form you see two large arm-like appendages ending in clench fists emerge.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Create Spawn","kind":"Su","details":"Any living creature slain by a mortuary cyclone's necrocone attack or energy drain attack becomes an undead creature in 1d4 rounds. Spawn are under the command of the mortuary cyclone that created them and remain enslaved until its destruction."},{"type":"Desecrating Aura","kind":"Su","details":"A mortuary cyclone emanates an aura of desecration within a 50-foot radius centered on its body. This functions as a desecrate spell (caster level 18th) as if the mortuary cyclone where a permanent fixture dedicated to its own deity. Clerics in the area take a -6 profane penalty on turning checks, undead within the area gain a +2 profane bonus on attack rolls, damage rolls, and saves, and undead created within the area have +2 hit points per HD. Further, anyone casting animate dead within 50 ft. of a mortuary cyclone creates as many as double the normal amount of undead (4 HD per caster level instead of 2 HD per caster level). A consecrate spell cast on a mortuary cyclone by a caster of 18th level or higher nullifies its desecrating aura for 1 minute per caster level."},{"type":"Necrocone","kind":"Su","details":"Once every 1d4 rounds, a mortuary cyclone can blast forth a mass of bone fragments, debris and negative energy in a 30-foot cone. Creatures caught in the cone take 6d6 points of damage. Half this damage is piercing damage, but the other half is from negative energy and isn't subject to resistance or immunity (unless the opponent is resistant or immune to negative energy effects). An affected creature that succeeds on a DC 27 Reflex save reduces the piercing damage by half. Undead within the area of a necrocone heal a number of hit points equal to the amount of negative energy damage (3d6) the attack would otherwise deal. An undead creature cannot gain temporary or bonus hit points from a mortuary cyclone's necrocone. The save DC is Charisma-based."},{"type":"Unholy Grace","kind":"Su","details":"A mortuary cyclone adds its Charisma modifier as a bonus on its saving throws and as a profane bonus to its Armor Class. (The statistics block already reflects these bonuses.)"}],"description":"A mortuary cyclone is an undead creature born when living creatures tamper with or desecrate a mass grave (either magically or naturally).\n\nThough not evil by nature, the destruction a mortuary cyclone deals and leaves in its wake is legendary. These creatures simply decide on a direction to move, and much like a natural occurring tornado, they move in that direction without regard to who or what stands in their way. A single mortuary cyclone is more than capable of destroying a village or small town in a very short time if left unchecked.\n\nA mortuary cyclone appears as a 20 foot tall or taller tornado composed of grave dirt, bone fragments, and body parts all swirling around in its whirlwind form.\n\nMortuary cyclones feed on the energy of living creatures. Such creatures caught in the path of a mortuary cyclone are sucked into its central form and pummeled by high speed winds, bone fragments, and negative energy. Slain creatures are deposited on the ground where they rise as undead \"slaves\" in command of the mortuary cyclone.\n\nA mortuary cyclone attacks by forming pseudo-fists from its whirlwind form and pummeling its foes or by absorbing them into its whirlwind (its favored method of attack). A mortuary cyclone simply has to move into a creature's space to pull it into it cyclonic form. It continues raining its fists down on creatures that avoid its whirlwind, all the while, firing a burst of bone fragments and negative energy at foes attempting to keep their distance.\n\nA mortuary cyclone's natural weapons are treated as magic weapons for the purpose of overcoming damage reduction.\n\nMortuary Cyclone Spawn A creature killed by a mortuary cyclone's necrocone rises as an undead creature in 1d4 rounds. The type is based on the creature's total HD.\n\n>>Total HD / Opponent Rises as\nLess than 10 HD | Zombie or skeleton\n11-15 HD | Wraith\n16-20 HD | Spectre\n21+ HD | Dread wraith"},{"name":"Quantum","cr":20,"xp":307200,"alignment":"N","size":"Huge","type":"aberration","subtypes":["extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":32,"ac_touch":15,"ac_flat_footed":28,"ac_mods":"+3 deflection, +4 Dex, +17 natural, -2 size","hp":357,"hd":"34d8+170 (+34)","hdvalue":34,"fort":18,"ref":17,"will":23,"defensive_abilities":["unstable form"],"dr":"15/adamantine","speed":[{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"5 tentacles +34 (2d6+11)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"disintegration"}],"strength":33,"dexterity":18,"constitution":21,"intelligence":11,"wisdom":14,"charisma":17,"baseatk":25,"cmb":38,"cmb_special":"+4 vs. bull rush","cmd":55,"cmd_special":"+4 vs. bull rush can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Awesome Blow"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Greater Bull Rush"},{"feat":"Greater Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Improved Lightning Reflexes"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Stand Still"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":41},{"skill":"Knowledge (planes)","value":37},{"skill":"Perception","value":47},{"skill":"Sense Motive","value":43}],"languages":["Common","Quantum"],"sq":[{"type":"quantum form"},{"type":"quantum movement"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature seems to have no true shape, as its outline flickers and changes seemingly at random. At first it appears to have four tentacles, then in a flicker eight more appear and waver menacingly before shimmering once more out of existence. Its general shape is serpentine, with an uncertain number of tentacles dangling beneath it, but the only constants are its six glowing eyes, three on each side of what must be its head.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Disintegration","kind":"Su","details":"Three times per day, as a full-round action, a quantum can attack with a single tentacle. If it hits, it sets up subatomic vibrations that shake apart the molecular structure of its opponent. The target must succeed on a DC 32 Fortitude save or take 40d6 points of damage. Even if the save succeeds, the target takes 10d6 points of damage. This effect functions as a disintegrate spell (CL 34th). A quantum can use this ability when it uses its quantum form. Each use by one of its forms counts against its daily use limit. The save DC is Constitution-based."},{"type":"Quantum Form","kind":"Su","details":"Three times per day and once per round, a quantum can move in such a way as to appear in two places at once, at a distance no greater than 30 ft. This is a free action that provokes an attack of opportunity and lasts only one round. While occupying two spaces simultaneously, each representation of the quantum can perform one independent standard action (including using the quantum's special attacks). Using this ability, the same quantum could attack two different opponents, or attack one opponent while opening a door to escape, and so on. At the end of the round, both instances of the quantum return to the space it originally occupied before activating this ability."},{"type":"Quantum Movement","kind":"Su","details":"At will a quantum can use the dimension door spell as a standard action (CL 34th)."},{"type":"Unstable Form","kind":"Su","details":"A quantum has a deflection bonus to its Armor Class equal to its Charisma bonus. Further, because it moves by means of short-distance teleportation, attacks aimed at a quantum have a 20% miss chance."}],"description":"The quantums hail from beyond and between all planes. The first quantum is said to have followed a lost band of adventurers back after they became lost on a planar journey.\n\nA quantum exists simultaneously in many dimensions at once, which gives it a flickering, seemingly insubstantial shape as if some mad god is continually creating and re-creating it on a whim. If its form could somehow be stabilized into only three dimensions, a quantum would resemble a flattened jellyfish with a knob at the top containing six unblinking eyes. It has an oblong body with many tentacles radiating out from beneath its body. The exact number of tentacles cannot be known, however, since stabilizing a quantum's shape is a task yet to be undertaken and may not even be possible.\n\nQuantums move by avoiding space entirely. A quantum hovers like some eerie jellyfish but doesn't fly by conventional means. Instead a quantum actually teleports short distances too fast for the eye to detect and in this manner it appears to be hovering. A quantum can also teleport across greater distances. At one moment a quantum can be in one space and then in an instant it is somewhere else, having never been at any point between. The flickering form of a quantum allows it to attack with one tentacle, two, six, as many as it needs. Attack-capable limbs seem to manifest themselves as they are needed, then vanish again as if they had never existed.\n\nA quantum lashes out at its foes with its tentacles. Against a particularly powerful opponent, it uses its disintegration attack. When facing multiple foes, a quantum uses its quantum form to better its odds or make its escape."},{"name":"Ravager Spawn","cr":20,"xp":307200,"alignment":"N","size":"Huge","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"tremorsense","modifier":"60 ft."}],"ac":40,"ac_touch":13,"ac_flat_footed":35,"ac_mods":"+5 Dex, +27 natural, -2 size","hp":495,"hd":"30d10+300 (+30)","hdvalue":30,"hp_mods":["regeneration 5 (epic-level weapons and artifacts)","vampiric healing"],"fort":29,"ref":22,"will":19,"defensive_abilities":["magic disruption (1 on d20)"],"dr":"15/epic","immunities":["energy drain"],"resists":[{"type":"death"},{"type":"energy","value":5}],"speed":[{"type":"land","speed":40},{"type":"burrow","speed":10}],"melee":"bite +37 (3d8+9/19-20/x3), 4 claws +37 (2d8+9/18-20)","space":"15 ft.","reach":"10 ft.","strength":28,"dexterity":20,"constitution":30,"intelligence":5,"wisdom":25,"charisma":18,"baseatk":30,"cmb":41,"cmb_special":"+2 vs. bull rush","cmd":56,"cmd_special":"+2 vs. bull rush, +4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Great Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Natural Armor (x3)"},{"feat":"Improved Natural Attack (bite)"},{"feat":"Improved Natural Attack (claw)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":40}],"sq":[{"type":"form-shifting"}],"environments":["any"],"organizations":["solitary","brood (2-8)"],"treasure":"none","description_visual":"This enormous creature stands 18 ft. high at the shoulders and has a body 30 ft. long. Its body is long and narrow, with eight stubby legs ending in ebon claws the size of large falchions. Its mouth is filled with sharp black teeth, and its eyes are jet-black orbs the size of dinner platters, set above a delicate muzzle like that of a bulldog. The body is hairless, covered with a thick, leathery crimson hide.","group":"Ravager","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Death Resistance","kind":"Ex","details":"A Ravager spawn possesses an innate resistance to effects that would kill or permanently incapacitate it, including petrification and imprisonment. Against such effects it is considered to automatically make any required saving throws."},{"type":"Energy Resistance","kind":"Ex","details":"A Ravager spawn possesses energy resistance against all forms of energy attack (fire, cold, electricity, acid, and sonic)."},{"type":"Form-Shifting","kind":"Ex","details":"A Ravager spawn can physically alter its physiology to take on one of the three listed forms: the crawler, the brawler, or the flier. Doing so takes one minute, and during this period it cannot take any other actions, though it isn't considered helpless."},{"type":"Magic Disruption","kind":"Su","details":"Every time a Ravager spawn comes into contact with a spell or spell-like or supernatural effect, there is a chance as indicated above that the magic doesn't affect it. In the case of ongoing effects, a new check is made each round."},{"type":"Regeneration","kind":"Ex","details":"A Ravager spawn treats all damage as subdual, except damage from epic-level weapons and artifacts."},{"type":"Vampiric Healing","kind":"Su","details":"Whenever a Ravager spawn hits with a melee attack, it is healed hit points equal to half the damage it inflicts on its opponent. This ability cannot heal it above its natural maximum hit points. This ability extends to its trample special attack, where applicable."}],"description":"The Ravager was created eons ago by a primeval race of beings who believed in the unity of three forces: body, mind, and spirit. In their ongoing war with another race of savages, they created several weapons of terrible power. The greatest of these is the living beast known only as the Ravager.\n\nThis beast was given incredible vitality, and the power to manipulate its own body to assume a form most advantageous to it: a crawling weasel-like form that can burrow, a hulking apelike humanoid form with greater reach and strength, and a winged form to allow it greater mobility and agility.\n\nAfter being used once or twice on the battlefield, those who created it realized its awesome danger and contained it in the strongest prison they could devise, suspended in time until it would once again be needed.\n\nHowever, due to the subsequent influence of Orcus near the vault where the Ravager was contained, the wards were damaged, and a taint of evil infected its quarantine. This has resulted in it reproducing asexually, and has granted the ravager an astonishing capacity for growth. For every week that it lives, it permanently gains 1 hit die. There is no known limit to how far this advancement can go before it either devastates the planet it lives on or collapses under its own weight.","credit":"Originally appearing in Rappan Athuk Reloaded (© Necromancer Games, 2006)"},{"name":"Ravager Spawn","cr":20,"xp":307200,"alignment":"N","size":"Huge","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"tremorsense","modifier":"60 ft."}],"ac":37,"ac_touch":13,"ac_flat_footed":32,"ac_mods":"+5 Dex, +24 natural, -2 size","hp":405,"hd":"30d10+210 (+30)","hdvalue":30,"hp_mods":["regeneration 5 (epic-level weapons and artifacts)","vampiric healing"],"fort":26,"ref":22,"will":19,"defensive_abilities":["magic disruption (1 on d20)"],"dr":"15/epic","immunities":["energy drain"],"resists":[{"type":"death"},{"type":"energy","value":5}],"speed":[{"type":"land","speed":50}],"melee":"bite +40 (3d6+12/x3), 2 claws +40 (1d12+12/15-20)","space":"15 ft.","reach":"15 ft.","strength":34,"dexterity":20,"constitution":24,"intelligence":5,"wisdom":25,"charisma":18,"baseatk":30,"cmb":43,"cmb_special":"+2 vs. bull rush","cmd":58,"cmd_special":"+2 vs. bull rush","feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Great Fortitude"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Stunning Critical"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Perception","value":40}],"sq":[{"type":"form-shifting"}],"environments":["any"],"organizations":["solitary","brood (2-8)"],"treasure":"none","description_visual":"Towering 35 ft. high is a massive, apelike creature, resting on two sets of powerfully muscled legs. A third set of arms, thick and corded with muscle, bulges out from its massive shoulders, ending with massive black claws. The mouth is filled with jagged black teeth, and glistening black eyes are set over a wide muzzle. Its skin is deep red, somewhat lighter on the underbelly.","group":"Ravager","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Death Resistance","kind":"Ex","details":"A Ravager spawn possesses an innate resistance to effects that would kill or permanently incapacitate it, including petrification and imprisonment. Against such effects it is considered to automatically make any required saving throws."},{"type":"Energy Resistance","kind":"Ex","details":"A Ravager spawn possesses energy resistance against all forms of energy attack (fire, cold, electricity, acid, and sonic)."},{"type":"Form-Shifting","kind":"Ex","details":"A Ravager spawn can physically alter its physiology to take on one of the three listed forms: the crawler, the brawler, or the flier. Doing so takes one minute, and during this period it cannot take any other actions, though it isn't considered helpless."},{"type":"Magic Disruption","kind":"Su","details":"Every time a Ravager spawn comes into contact with a spell or spell-like or supernatural effect, there is a chance as indicated above that the magic doesn't affect it. In the case of ongoing effects, a new check is made each round."},{"type":"Regeneration","kind":"Ex","details":"A Ravager spawn treats all damage as subdual, except damage from epic-level weapons and artifacts."},{"type":"Vampiric Healing","kind":"Su","details":"Whenever a Ravager spawn hits with a melee attack, it is healed hit points equal to half the damage it inflicts on its opponent. This ability cannot heal it above its natural maximum hit points. This ability extends to its trample special attack, where applicable."}],"description":"The Ravager was created eons ago by a primeval race of beings who believed in the unity of three forces: body, mind, and spirit. In their ongoing war with another race of savages, they created several weapons of terrible power. The greatest of these is the living beast known only as the Ravager.\n\nThis beast was given incredible vitality, and the power to manipulate its own body to assume a form most advantageous to it: a crawling weasel-like form that can burrow, a hulking apelike humanoid form with greater reach and strength, and a winged form to allow it greater mobility and agility.\n\nAfter being used once or twice on the battlefield, those who created it realized its awesome danger and contained it in the strongest prison they could devise, suspended in time until it would once again be needed.\n\nHowever, due to the subsequent influence of Orcus near the vault where the Ravager was contained, the wards were damaged, and a taint of evil infected its quarantine. This has resulted in it reproducing asexually, and has granted the ravager an astonishing capacity for growth. For every week that it lives, it permanently gains 1 hit die. There is no known limit to how far this advancement can go before it either devastates the planet it lives on or collapses under its own weight.","credit":"Originally appearing in Rappan Athuk Reloaded (© Necromancer Games, 2006)"}];
